        max_unique = unique
        max_word = word
    elif unique == max_unique:
        if word < max_word:
            max_word = word
return max_word

# Check if the length of operator list is equal to the length of operand list minus one
if len(operator) != len(operand) - 1:
    return None

# Initialize the result with the first operand
result = operand[0]

# Iterate through the operator list
for i in range(len(operator)):
    # Check the operator
    if operator[i] == '+':
        result += operand[i + 1]
    elif operator[i] == '-':
        result -= operand[i + 1]
    elif operator[i] == '*':
        result *= operand[i + 1]
    elif operator[i] == '//':
        result //= operand[i + 1]
    elif operator[i] == '**':
        result **= operand[i + 1]

return result

# Check if the string contains any letters
if not any(c.isalpha() for c in s):
    # If no letters, reverse the string
    return s[::-1]
else:
    # If contains letters, reverse case of letters
    result = ""
    for c in s:
        if c.isalpha():
            if c.islower():
                result += c.upper()
            else:
                result += c.lower()
        else:
            result += c
    return result

